const listReportingReleaseApprovals = `-- name: ListReportingReleaseApprovals :many
SELECT approval_role, actor_user_id
  FROM reporting_release_approvals
 WHERE release_id = $1
 ORDER BY approval_role ASC, created_at ASC, approval_id ASC
`

type ListReportingReleaseApprovalsRow struct {
	ApprovalRole string      `json:"approval_role"`
	ActorUserID  pgtype.UUID `json:"actor_user_id"`
}

func (q *Queries) ListReportingReleaseApprovals(ctx context.Context, releaseID pgtype.UUID) ([]ListReportingReleaseApprovalsRow, error) {
	rows, err := q.db.Query(ctx, listReportingReleaseApprovals, releaseID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListReportingReleaseApprovalsRow
	for rows.Next() {
		var i ListReportingReleaseApprovalsRow
		if err := rows.Scan(&i.ApprovalRole, &i.ActorUserID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

